{
  "sql": "SELECT COUNT(DISTINCT seller_id) AS num_vendedores, SUM(ingresos) AS ingresos_totales FROM ( SELECT seller_id, SUM(price) AS ingresos, AVG(review_score_promedio) AS calificacion, SUM(CASE WHEN entrega_con_retraso = 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(order_id) AS pct_retrasos FROM vw_ingresos_por_vendedor INNER JOIN vw_entregas_retrasos ON vw_ingresos_por_vendedor.seller_id = vw_entregas_retrasos.seller_id GROUP BY seller_id HAVING COUNT(DISTINCT order_id) >= 30 ) WHERE (ingresos >= ( SELECT PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY ingresos) FROM ( SELECT SUM(price) AS ingresos FROM vw_ingresos_por_vendedor WHERE seller_id IN ( SELECT seller_id FROM vw_ingresos_por_vendedor GROUP BY seller_id HAVING COUNT(DISTINCT order_id) >= 30 ) ) ) AND (calificacion < 3.5 OR pct_retrasos >= 15 )"
}
